/// Default wholesale discount applied by downstream margin math to UK retail
/// benchmark prices (Amazon / eBay consumer listings).
///
/// 3000 bps = 30 % → estimated wholesale ≈ retail × 0.70.
///
/// Store RAW retail in `supplier_quotes.unit_price_gbp_pence` and tag with
/// `price_signal_role = "uk_retail_benchmark"`. Do NOT apply this discount at
/// quote-write time — Stage 10+ margin computation multiplies `(10000 - bps)`
/// so this constant can be tuned without re-scraping.
///
/// Operator-adjustable range: 2000..=4000 bps (20 %..=40 %).
#[allow(dead_code)]
const DEFAULT_UK_RETAIL_WHOLESALE_DISCOUNT_BPS: i64 = 3000;
const QUOTE_ROLE_UK_SIDE: &str = "uk_side_quote";
const QUOTE_ROLE_CHINA_IMPORT: &str = "china_import_quote";
const COVERAGE_STATE_ATTEMPTED_NO_QUOTE: &str = "attempted_no_quote";
const COVERAGE_STATE_ATTEMPTED_FAILED: &str = "attempted_failed";
const COVERAGE_STATE_USABLE_QUOTE_AVAILABLE: &str = "usable_quote_available";
const COVERAGE_STATE_BLOCKED_CAPTCHA: &str = "blocked_captcha";
const COVERAGE_STATE_BLOCKED_AUTH: &str = "blocked_auth";
const BASIS_TWO_SIDED_SUPPLIER_COMPARISON: &str = "two_sided_supplier_comparison";
const BASIS_SINGLE_SIDE_RETAIL_DISCOUNT_FALLBACK: &str = "single_side_retail_discount_fallback";
const BASIS_SINGLE_SIDE_WHOLESALE_FALLBACK: &str = "single_side_wholesale_fallback";
const BASIS_MISSING_REQUIRED_QUOTE_ROLE_ATTEMPT: &str = "missing_required_quote_role_attempt";

/// How many `product_candidates` a single marketplace-search PTY session
/// should handle. Keeps session token budgets tractable and bounds
/// blast-radius on a single skill failure.
///
/// Tuned down from 5 → 3 on 2026-04-21 after observing that Alibaba's
/// per-session anti-bot rate limiter started CAPTCHA-blocking candidates
/// 4 and 5 in a 5-candidate batch, even with CDP attached to a logged-in
/// Chrome. Three candidates per session lets the Alibaba skill finish
/// all three cleanly; the 57 searchable-candidate pool now needs ~2
/// back-to-back runs per source instead of 1.
const MARKETPLACE_SEARCH_BATCH_SIZE: i64 = 3;

/// Minimum seconds a marketplace-search source must idle before we spawn
/// another PTY run against it, IF the source was recently CAPTCHA-blocked.
/// Computed from `MAX(executed_at)` of rows with
/// `search_failure_mode = 'SOURCE_CAPTCHA_BLOCKED'` for the source.
///
/// Clean sources (Gem Imports, MX Wholesale, eBay UK) have zero such rows
/// so the cool-down is effectively skipped for them. It only binds on
/// CAPTCHA-prone sources (Alibaba, Amazon UK). First-cut value: 180 s.
/// Tune up to 300-600 s if operator observes repeat CAPTCHAs even with
/// the cool-down active.
const MARKETPLACE_SEARCH_INTER_SESSION_COOLDOWN_SECONDS: i64 = 180;
const LANDED_COST_BATCH_SIZE: i64 = 20;
// Live customs, marketplace sizing, and freight lookups can each involve
// browser/API evidence gathering before the skill writes its result contract.
const LANDED_COST_SKILL_TIMEOUT_SECONDS: u64 = 300;
const LANDED_COST_STAGE_NAME: &str = "landed cost";
const LANDED_COST_SCOPE_KIND: &str = "candidate_quote";
const LANDED_COST_UK_INSTALLATION_LABOUR_JOB_KIND: &str = "landed_cost_uk_installation_labour";
const OVERLAY_LABOUR_COST_SKILL_ID: &str = "validation/overlay-labour-cost";
const LABOUR_OVERLAY_REVIEW_REQUIRED: &str = "LABOUR_OVERLAY_REVIEW_REQUIRED";
const UK_INSTALLATION_LABOUR_RATE_TABLE_VERSION: &str = "uk-installation-labour-2026-q2";
// Stage 11 CDP / captcha resilience knobs (handoff stage-11-hardening-cdp-resilience).
// `STAGE11_SKILL_RETRY_PER_ATTEMPT_SECONDS` bounds each SeaRates attempt only —
// the outer 300s bound still gates total time. Live CDP validation showed the
// Codex-backed skill can exceed 60s before writing its result even on the fast
// GraphQL path, so the default leaves enough room for model startup plus one
// browser query while preserving the 15s/45s retry backoff contract.
const STAGE11_SKILL_RETRY_MAX_ATTEMPTS: u32 = 3;
const STAGE11_SKILL_RETRY_PER_ATTEMPT_SECONDS_DEFAULT: u64 = 180;
const STAGE11_SKILL_RETRY_PER_ATTEMPT_SECONDS_ENV: &str = "STAGE11_SKILL_RETRY_PER_ATTEMPT_SECONDS";
const STAGE11_SKILL_RETRY_BACKOFF_1_SECONDS_DEFAULT: u64 = 15;
const STAGE11_SKILL_RETRY_BACKOFF_2_SECONDS_DEFAULT: u64 = 45;
const STAGE11_SKILL_RETRY_BACKOFFS_ENV: &str = "STAGE11_SKILL_RETRY_BACKOFFS_SECONDS";
const STAGE11_FREIGHT_CACHE_TTL_DAYS_DEFAULT: u64 = 7;
const STAGE11_FREIGHT_CACHE_TTL_DAYS_ENV: &str = "STAGE11_FREIGHT_CACHE_TTL_DAYS";
// Stage 11 freshness windows (obep / testproject1-obep): explicit, policy-driven TTLs
// for the three rerun-able data classes. A stored lookup is "stale" once its checked-at
// timestamp is older than its window; stale/missing → rerun rather than reuse.
// FX moves fastest (daily), freight reuses its existing 7-day cache window, tariff/duty
// schedules change slowly (monthly cadence).
const STAGE11_TARIFF_FRESHNESS_DAYS_DEFAULT: u64 = 30;
const STAGE11_TARIFF_FRESHNESS_DAYS_ENV: &str = "STAGE11_TARIFF_FRESHNESS_DAYS";
