#[allow(clippy::struct_excessive_bools)]
#[derive(Debug, Clone, Parser)]
#[command(
    name = "daemon",
    version,
    about = "Layer 1 thin local runner bootstrap"
)]
struct Cli {
    /// Start the daemon, write readiness artifacts, and exit cleanly.
    #[arg(long, default_value_t = false)]
    dry_run: bool,

    /// Runtime state root containing the local `SQLite` database.
    #[arg(long, default_value = "state")]
    state_root: PathBuf,

    /// Runtime directory containing the lock, socket, and descriptor.
    #[arg(long, default_value = "runtime")]
    runtime_dir: PathBuf,

    /// Artifact root for captured bytes, run manifests, and opportunity manifests.
    #[arg(long, default_value = "artifacts")]
    artifact_root: PathBuf,

    /// When enabled, keep serving handshake connections until the daemon exits.
    #[arg(
        long,
        default_value_t = false,
        conflicts_with_all = ["serve_once", "ingest", "skill_path", "dry_run", "pipeline"]
    )]
    serve: bool,

    /// When enabled, accept exactly one handshake before exiting.
    #[arg(long, default_value_t = false, conflicts_with = "serve")]
    serve_once: bool,

    /// Run the manual live-loop trigger for the declared source id.
    #[arg(long)]
    ingest: Option<String>,

    /// Run a bound skill under daemon control.
    #[arg(long)]
    skill_path: Option<PathBuf>,

    /// Optional JSON object containing job parameters for `--skill-path`.
    #[arg(long)]
    job_parameters_json: Option<String>,

    /// Select the agent CLI adapter to use for this run (`claude` or `codex`).
    #[arg(long = "agent-cli")]
    adapter_choice: Option<String>,

    /// Override the selected agent CLI program path.
    #[arg(long)]
    agent_cli_program: Option<PathBuf>,

    /// Fixture file used by tests to drive deterministic live-loop execution.
    #[arg(long, hide = true)]
    fixture_path: Option<PathBuf>,

    /// Run deterministic pipeline stages on already-ingested data for the given source.
    #[arg(long)]
    pipeline: Option<String>,

    /// Run one deterministic scheduler tick, drain queued work, and exit.
    #[arg(
        long,
        hide = true,
        default_value_t = false,
        requires = "tick_now",
        conflicts_with_all = [
            "serve",
            "serve_once",
            "ingest",
            "skill_path",
            "dry_run",
            "pipeline",
            "run_next_job",
            "run_bid_workflow",
            "capture_decision",
            "capture_clarification",
            "withdraw_clarification",
            "withdraw_decision",
            "list_decisions"
        ]
    )]
    run_scheduler_once: bool,

    /// RFC3339 instant supplied to `--run-scheduler-once`.
    #[arg(
        long,
        hide = true,
        value_name = "RFC3339",
        requires = "run_scheduler_once"
    )]
    tick_now: Option<String>,

    /// Claim and execute exactly one pending workflow job. Hidden because it is
    /// currently only used by deterministic integration tests and PDF queue work.
    #[arg(
        long,
        hide = true,
        default_value_t = false,
        conflicts_with_all = [
            "serve",
            "serve_once",
            "ingest",
            "skill_path",
            "dry_run",
            "pipeline",
            "run_scheduler_once",
            "run_bid_workflow"
        ]
    )]
    run_next_job: bool,

    /// Re-run a bid workflow job through the manual recovery readiness boundary.
    #[arg(
        long,
        value_name = "BID_JOB_ID",
        conflicts_with_all = [
            "serve",
            "serve_once",
            "ingest",
            "skill_path",
            "dry_run",
            "pipeline",
            "run_scheduler_once",
            "run_next_job",
            "capture_decision",
            "capture_clarification",
            "withdraw_clarification",
            "withdraw_decision",
            "list_decisions"
        ]
    )]
    run_bid_workflow: Option<String>,

    // -- Stage 14 — operator decision capture (CLI Phase 1) ---------------
    /// Capture a final operator disposition (`approve`/`reject`/`watch`) for a
    /// process whose Stage 13 manifest already exists. Inserts a row into
    /// `pending_operator_intents` and supersedes any prior active intent.
    #[arg(long, value_name = "PROCESS_ID")]
    capture_decision: Option<String>,

    /// Disposition for `--capture-decision`. One of: approve, reject, watch.
    #[arg(long, requires = "capture_decision")]
    disposition: Option<String>,

    /// Idempotency key for `--capture-decision`. Required and UNIQUE — re-running
    /// with the same key is a no-op.
    #[arg(long, requires = "capture_decision")]
    idempotency_key: Option<String>,

    /// Optional free-form reasoning saved as `decision_note` on the intent row.
    #[arg(long)]
    reasoning: Option<String>,

    /// Capture a clarification override for a candidate. Persists into
    /// `operator_input_overrides`; Stages 10/11 read it on next pipeline run.
    #[arg(long, value_name = "PROCESS_ID")]
    capture_clarification: Option<String>,

    /// `product_candidate_id` for `--capture-clarification` /
    /// `--withdraw-clarification`.
    #[arg(long)]
    candidate_id: Option<String>,

    /// `reason_code` for `--capture-clarification` / `--withdraw-clarification`.
    /// One of: `quantity_basis_undetermined`, `quantity_basis_unaligned`,
    /// `awaiting_rfq_quote`, `no_pricing_signal`.
    #[arg(long)]
    reason_code: Option<String>,

    /// JSON payload string for `--capture-clarification`. Schema depends on
    /// `--reason-code`.
    #[arg(long)]
    payload: Option<String>,

    /// Optional operator note attached to the override row.
    #[arg(long)]
    note: Option<String>,

    /// Withdraw an active clarification override. Sets `withdrawn_at`; row stays
    /// in the table for audit.
    #[arg(long, value_name = "PROCESS_ID")]
    withdraw_clarification: Option<String>,

    /// Withdraw a captured decision by `idempotency_key`. Sets the intent's
    /// `status='withdrawn'`.
    #[arg(long, value_name = "IDEMPOTENCY_KEY")]
    withdraw_decision: Option<String>,

    /// List captured decisions (read-only). Optional filters: `--process-id` and
    /// `--list-status-filter`.
    #[arg(long, default_value_t = false)]
    list_decisions: bool,

    /// Optional filter: limit `--list-decisions` to one process.
    #[arg(long, value_name = "PROCESS_ID")]
    process_id: Option<String>,

    /// Optional filter: limit `--list-decisions` to a single status
    /// (`queued`/`stale`/`superseded`/`withdrawn`).
    #[arg(long)]
    list_status_filter: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AgentCliKind {
    Claude,
    Codex,
}

impl AgentCliKind {
    fn parse(raw: &str) -> Result<Self> {
        match raw {
            "claude" => Ok(Self::Claude),
            "codex" => Ok(Self::Codex),
            other => bail!("unsupported agent_cli `{other}`"),
        }
    }

    const fn as_str(self) -> &'static str {
        match self {
            Self::Claude => "claude",
            Self::Codex => "codex",
        }
    }

    const fn env_key(self) -> &'static str {
        match self {
            Self::Claude => "DAEMON_CLAUDE_PROGRAM",
            Self::Codex => "DAEMON_CODEX_PROGRAM",
        }
    }
}

