#[derive(Debug, Clone, Serialize, Deserialize)]
struct Stage11Issue {
    code: String,
    #[serde(default)]
    message: String,
    #[serde(default = "stage11_default_issue_severity")]
    severity: String,
}

fn stage11_default_issue_severity() -> String {
    "warning".to_owned()
}

impl Stage11Issue {
    fn warning(code: &str, message: impl Into<String>) -> Self {
        Self {
            code: code.to_owned(),
            message: message.into(),
            severity: "warning".to_owned(),
        }
    }

    fn blocked(code: &str, message: impl Into<String>) -> Self {
        Self {
            code: code.to_owned(),
            message: message.into(),
            severity: "blocked".to_owned(),
        }
    }
}

#[derive(Debug, Clone)]
struct SupplierCostBasis {
    supplier_cost_gbp_pence: i64,
    basis: String,
    quantity: f64,
    quantity_unit: Option<String>,
    warnings: Vec<Stage11Issue>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BasisUndeterminedReason {
    /// Revenue and the supplier's cost basis are on incompatible scales (e.g.
    /// framework-total revenue vs per-pack listing price), so dividing one by
    /// the other yields a meaningless order quantity.
    RevenueCostScaleMismatch,
    /// No quantity signal of any kind is available (no candidate qty, no lot
    /// estimated value, no MOQ, no plausible `quoted_quantity`).
    NoQuantityAnywhere,
    /// Multiple signals are present but disagree, and no rule chooses among
    /// them safely.
    ConflictingSignals,
}

impl BasisUndeterminedReason {
    const fn as_str(self) -> &'static str {
        match self {
            Self::RevenueCostScaleMismatch => "revenue_cost_scale_mismatch",
            Self::NoQuantityAnywhere => "no_quantity_anywhere",
            Self::ConflictingSignals => "conflicting_signals",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
enum OrderQuantityBasis {
    FromContractValue {
        qty: f64,
        contract_value_gbp_pence: i64,
        basis_unit: Option<String>,
    },
    FromLotQuantity {
        qty: f64,
        basis_unit: Option<String>,
    },
    RfqRequired {
        fallback_qty: f64,
        basis_unit: Option<String>,
    },
    SupplierCapacity {
        qty: f64,
        basis_unit: Option<String>,
    },
    FromOperatorOverride {
        qty: f64,
        basis_unit: Option<String>,
    },
    /// Stage 11 cannot infer a meaningful order quantity from the available
    /// inputs. Margins must be persisted as zero with low commercial confidence
    /// until an operator override or richer evidence resolves the ambiguity.
    BasisUndetermined {
        reason: BasisUndeterminedReason,
        note: String,
        basis_unit: Option<String>,
    },
}

impl OrderQuantityBasis {
    const fn kind(&self) -> &'static str {
        match self {
            Self::FromContractValue { .. } => "from_contract_value",
            Self::FromLotQuantity { .. } => "from_lot_quantity",
            Self::RfqRequired { .. } => "rfq_required",
            Self::SupplierCapacity { .. } => "supplier_capacity",
            Self::FromOperatorOverride { .. } => "from_operator_override",
            Self::BasisUndetermined { .. } => "basis_undetermined",
        }
    }

    const fn source(&self) -> &'static str {
        match self {
            Self::FromContractValue { .. } => "expected_value_divided_by_unit_price",
            Self::FromLotQuantity { .. } => "product_candidate_quantity",
            Self::RfqRequired { .. } => "minimum_order_quantity_or_one_unit_fallback",
            Self::SupplierCapacity { .. } => "supplier_quote_quoted_quantity",
            Self::FromOperatorOverride { .. } => "operator_input_overrides",
            Self::BasisUndetermined { .. } => "insufficient_inputs",
        }
    }

    const fn supplier_cost_basis(&self) -> &'static str {
        match self {
            Self::FromContractValue { .. } => "contract_value_order_quantity",
            Self::FromLotQuantity { .. } => "lot_quantity_order_quantity",
            Self::RfqRequired { .. } => "rfq_required_minimum_order_quantity",
            Self::SupplierCapacity { .. } => "supplier_capacity_quoted_quantity",
            Self::FromOperatorOverride { .. } => "operator_override_order_quantity",
            Self::BasisUndetermined { .. } => "basis_undetermined_per_unit_screening",
        }
    }

    /// Returns the inferred order quantity. For `BasisUndetermined` we return
    /// 1.0 so per-unit landed cost remains meaningful — net margin is forced
    /// to zero in persistence regardless.
    const fn quantity(&self) -> f64 {
        match self {
            Self::FromContractValue { qty, .. }
            | Self::FromLotQuantity { qty, .. }
            | Self::SupplierCapacity { qty, .. }
            | Self::FromOperatorOverride { qty, .. } => *qty,
            Self::RfqRequired { fallback_qty, .. } => *fallback_qty,
            Self::BasisUndetermined { .. } => 1.0,
        }
    }

    fn unit(&self) -> Option<&str> {
        match self {
            Self::FromContractValue { basis_unit, .. }
            | Self::FromLotQuantity { basis_unit, .. }
            | Self::RfqRequired { basis_unit, .. }
            | Self::SupplierCapacity { basis_unit, .. }
            | Self::FromOperatorOverride { basis_unit, .. }
            | Self::BasisUndetermined { basis_unit, .. } => basis_unit.as_deref(),
        }
    }

    fn to_json(&self) -> Value {
        let mut payload = json!({
            "kind": self.kind(),
            "qty": self.quantity(),
            "unit": self.unit(),
            "source": self.source(),
        });
        match self {
            Self::FromContractValue {
                contract_value_gbp_pence,
                ..
            } => {
                payload["contract_value_gbp_pence"] = json!(contract_value_gbp_pence);
            }
            Self::BasisUndetermined { reason, note, .. } => {
                payload["reason"] = json!(reason.as_str());
                payload["note"] = json!(note);
            }
            _ => {}
        }
        payload
    }

    fn screening_uncertainty_warning(&self) -> Option<Stage11Issue> {
        match self {
            Self::RfqRequired { .. } => Some(Stage11Issue::warning(
                "screening_only_quantity_uncertainty",
                "Stage 11 did not have an order quantity, so shipment and supplier cost use the selected quote minimum-order fallback until an RFQ quantity is known.",
            )),
            Self::SupplierCapacity { .. } => Some(Stage11Issue::warning(
                "screening_only_quantity_uncertainty",
                "Stage 11 had no order quantity or MOQ, so shipment and supplier cost use the supplier listing quantity as a screening-only capacity fallback.",
            )),
            Self::BasisUndetermined { reason, note, .. } => Some(Stage11Issue::warning(
                "QUANTITY_BASIS_UNDETERMINED_NO_OPERATOR_OVERRIDE",
                format!(
                    "Stage 11 could not infer a meaningful order quantity ({reason}); gross and net margins are persisted as zero until an operator override clarifies the basis. Detail: {note}",
                    reason = reason.as_str(),
                ),
            )),
            Self::FromContractValue { .. }
            | Self::FromLotQuantity { .. }
            | Self::FromOperatorOverride { .. } => None,
        }
    }

    /// True when the persistence layer must zero out margins and pin
    /// commercial confidence to the screening floor (1000 bps) — i.e. the
    /// basis is honestly low signal without an operator-supplied quantity.
    const fn requires_zero_margin_calibration(&self) -> bool {
        matches!(
            self,
            Self::BasisUndetermined { .. } | Self::RfqRequired { .. }
        )
    }
}

#[derive(Debug, Clone)]
struct LandedCostSkillRunOutcome {
    job_id: String,
    session_id: String,
    skill_version: String,
    result_json: Option<Value>,
    failure_message: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LabourOverlayRoute {
    NotRequired,
    Pass,
    Review,
}

impl LabourOverlayRoute {
    const fn as_str(self) -> &'static str {
        match self {
            Self::NotRequired => "not_required",
            Self::Pass => "pass",
            Self::Review => "review",
        }
    }
}

#[derive(Debug, Clone)]
struct UkInstallationLabourSkillOutcome {
    basis: Option<InstallationLabourCostBasis>,
    status: String,
    skill_run: Option<LandedCostSkillRunOutcome>,
    labour_overlay_route: LabourOverlayRoute,
    labour_overlay_reason: Option<String>,
}

impl UkInstallationLabourSkillOutcome {
    fn skipped_no_requirement() -> Self {
        Self {
            basis: None,
            status: "not_required".to_owned(),
            skill_run: None,
            labour_overlay_route: LabourOverlayRoute::NotRequired,
            labour_overlay_reason: None,
        }
    }

    fn blocked(skill_run: LandedCostSkillRunOutcome) -> Self {
        Self {
            basis: Some(InstallationLabourCostBasis::default()),
            status: "blocked".to_owned(),
            skill_run: Some(skill_run),
            labour_overlay_route: LabourOverlayRoute::Review,
            labour_overlay_reason: Some("worker_result_unavailable_or_invalid".to_owned()),
        }
    }

    fn from_result(
        result: UkInstallationLabourResult,
        skill_run: LandedCostSkillRunOutcome,
    ) -> Self {
        let status = result.status.clone();
        let has_blockers = !result.blockers.is_empty();
        let worker_blocked = matches!(result.status.as_str(), "blocked")
            || matches!(result.labour_status.as_str(), "blocked");
        let labour_overlay_route = if worker_blocked || has_blockers {
            LabourOverlayRoute::Review
        } else {
            LabourOverlayRoute::Pass
        };
        let labour_overlay_reason = if worker_blocked {
            Some("worker_status_blocked".to_owned())
        } else if has_blockers {
            Some("validator_rejected_worker_result".to_owned())
        } else {
            None
        };
        Self {
            basis: Some(result.into()),
            status,
            skill_run: Some(skill_run),
            labour_overlay_route,
            labour_overlay_reason,
        }
    }

    const fn basis(&self) -> Option<&InstallationLabourCostBasis> {
        self.basis.as_ref()
    }

    const fn skill_run(&self) -> Option<&LandedCostSkillRunOutcome> {
        self.skill_run.as_ref()
    }

    const fn labour_overlay_route(&self) -> LabourOverlayRoute {
        self.labour_overlay_route
    }

    fn labour_overlay_reason(&self) -> Option<&str> {
        self.labour_overlay_reason.as_deref()
    }
}

