    fn bootstrap_manifest_render_runtime()
    -> Result<(tempfile::TempDir, super::RuntimeBootstrap, Cli)> {
        let temp = tempdir()?;
        let state_root = temp.path().join("state");
        let runtime_dir = temp.path().join("runtime");
        let artifact_root = temp.path().join("artifacts");
        let cli = Cli::parse_from([
            "daemon",
            "--serve",
            "--state-root",
            state_root.to_str().expect("utf8 state root"),
            "--runtime-dir",
            runtime_dir.to_str().expect("utf8 runtime dir"),
            "--artifact-root",
            artifact_root.to_str().expect("utf8 artifact root"),
        ]);
        let runtime = bootstrap_runtime(&cli)?;
        Ok((temp, runtime, cli))
    }

    #[test]
    fn autonomous_worker_runtime_owns_state_db_connection_and_shares_arbiter() -> Result<()> {
        let (_temp, runtime, cli) = bootstrap_manifest_render_runtime()?;
        let mut worker_runtime =
            runtime.autonomous_worker_runtime(super::AutonomousWorkerLane::PtyBrowser, &cli)?;

        let serve_connection = std::ptr::from_ref::<Connection>(runtime.state_db.connection());
        let worker_connection =
            std::ptr::from_ref::<Connection>(worker_runtime.state_db.connection());
        assert_ne!(serve_connection, worker_connection);
        assert_eq!(worker_runtime.state_db_path, runtime.state_db_path);
        assert_eq!(worker_runtime.artifact_root, runtime.artifact_root);
        assert!(std::sync::Arc::ptr_eq(
            &worker_runtime.resource_arbiter,
            &runtime.resource_arbiter
        ));

        worker_runtime.state_db_mut().connection_mut().execute(
            "CREATE TABLE autonomous_worker_runtime_probe (id TEXT PRIMARY KEY)",
            [],
        )?;
        worker_runtime.state_db_mut().connection_mut().execute(
            "INSERT INTO autonomous_worker_runtime_probe (id) VALUES ('worker-write')",
            [],
        )?;
        let count: i64 = runtime.state_db.connection().query_row(
            "SELECT COUNT(*) FROM autonomous_worker_runtime_probe",
            [],
            |row| row.get(0),
        )?;
        assert_eq!(count, 1);

        Ok(())
    }

    #[test]
    fn autonomous_worker_lane_kind_filters_are_disjoint_and_complete() {
        let pty_kinds = super::AutonomousWorkerLane::PtyBrowser.claimable_kinds();
        let coverage_kinds = super::AutonomousWorkerLane::CoverageDeterministic.claimable_kinds();

        assert_eq!(pty_kinds, ["sync_source", "source_health", "auth_refresh"]);
        assert_eq!(
            coverage_kinds,
            [
                "commercial_sweep",
                "validation_cross_model_audit",
                "validation_calibration_readiness_sweep",
            ]
        );

        let pty_set = pty_kinds.iter().copied().collect::<BTreeSet<_>>();
        let coverage_set = coverage_kinds.iter().copied().collect::<BTreeSet<_>>();
        assert!(pty_set.is_disjoint(&coverage_set));
        assert_eq!(pty_set.len() + coverage_set.len(), 6);
    }

    #[test]
    fn autonomous_worker_threads_spawn_both_lanes_and_shutdown_idle() -> Result<()> {
        let (_temp, runtime, cli) = bootstrap_manifest_render_runtime()?;
        let threads = super::spawn_autonomous_worker_threads(&runtime, &cli)?;
        let lanes = threads
            .iter()
            .map(|thread| thread.lane)
            .collect::<BTreeSet<_>>();

        assert_eq!(threads.len(), 2);
        assert!(lanes.contains(&super::AutonomousWorkerLane::PtyBrowser));
        assert!(lanes.contains(&super::AutonomousWorkerLane::CoverageDeterministic));
        drop(threads);
        Ok(())
    }

