    fn write_fake_cron_handler_claude(root: &Path) -> Result<std::path::PathBuf> {
        let state_dir = root.join("fake-source-health-claude");
        fs::create_dir_all(&state_dir)?;
        fs::write(
            state_dir.join("probe.json"),
            serde_json::to_vec_pretty(&json!({
                "auth_healthy": true,
                "structured_output": true,
                "pty_viable": true,
                "browser_tools": true,
            }))?,
        )?;
        fs::write(
            state_dir.join("result-source-health.json"),
            serde_json::to_vec_pretty(&json!({
                "source_id": FTS_SOURCE_ID,
                "health_state": "green",
                "checks": {
                    "reachability": "passed",
                    "fingerprint": "passed",
                    "auth_state": "anonymous_ok",
                    "locale": "passed",
                    "challenge_rate": "passed",
                    "minimal_extraction": "passed",
                },
                "sample_item_count": 1,
            }))?,
        )?;
        fs::write(
            state_dir.join("result-auth-signin-procontract.json"),
            serde_json::to_vec_pretty(&json!({
                "signin_status": "signed_in",
                "autofill_fired": true,
                "submit_outcome": "signed_in",
                "redirected_to": "https://procontract.due-north.com/",
                "cdp_state": "connected",
                "captcha_intercepted": false,
                "warnings": ["fake-claude auth-refresh evidence"],
                "blockers": [],
            }))?,
        )?;
        let program = state_dir.join("claude");
        fs::write(
            &program,
            format!(
                "#!/bin/sh\nset -eu\nstate_dir=\"{}\"\ncase \"${{1-}}\" in\n  --version|-v)\n    printf 'claude 1.2.3\\n'\n    exit 0\n    ;;\n  probe)\n    cat \"$state_dir/probe.json\"\n    exit 0\n    ;;\nesac\ncase \"$*\" in\n  *auth-signin/procontract*)\n    cp \"$state_dir/result-auth-signin-procontract.json\" result.json\n    ;;\n  *)\n    cp \"$state_dir/result-source-health.json\" result.json\n    ;;\nesac\nprintf '{{\"event\":\"checkpoint\",\"seq\":1,\"path\":\"result.json\"}}\\n'\n",
                state_dir.display()
            ),
        )?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mut permissions = fs::metadata(&program)?.permissions();
            permissions.set_mode(0o755);
            fs::set_permissions(&program, permissions)?;
        }
        Ok(program)
    }

    fn seed_running_cron_job(conn: &Connection, job_id: &str, kind: &str) -> Result<()> {
        let lease_expires_at = (Utc::now() + chrono::Duration::minutes(5)).to_rfc3339();
        conn.execute(
            "\
            INSERT INTO workflow_jobs (
              id, kind, status, lease_owner, lease_expires_at,
              attempt_count, input_payload, started_at, created_at
            ) VALUES (?1, ?2, 'running', 'local-daemon', ?3, 1, ?4, ?5, ?5)
            ",
            params![
                job_id,
                kind,
                lease_expires_at,
                json!({"job_id": job_id, "kind": kind}).to_string(),
                "2026-06-08T12:00:00Z",
            ],
        )?;
        Ok(())
    }

