    #[allow(clippy::too_many_lines)]
    fn assert_new_cron_handler_side_effects(conn: &Connection) -> Result<()> {
        let source_health_count: i64 = conn.query_row(
            "\
            SELECT COUNT(*)
            FROM source_runtime_state
            WHERE source_id = ?1
              AND last_canary_at IS NOT NULL
              AND last_canary_result = 'passed'
              AND circuit_state = 'closed'
            ",
            params![FTS_SOURCE_ID],
            |row| row.get(0),
        )?;
        assert_eq!(source_health_count, 1);

        let source_health_session_count: i64 = conn.query_row(
            "\
            SELECT COUNT(*)
            FROM agent_session_logs
            WHERE job_id = 'job-source-health'
              AND skill_path LIKE '%source-health/fts%'
            ",
            [],
            |row| row.get(0),
        )?;
        assert_eq!(source_health_session_count, 1);

        let auth_refresh_row: (String, String, String, String) = conn.query_row(
            "\
            SELECT source_id, signin_status, cdp_state, result_json
            FROM auth_refresh_results
            WHERE workflow_job_id = 'job-auth-refresh'
            ",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )?;
        assert_eq!(auth_refresh_row.0, PROCONTRACT_DISCOVER_SOURCE_ID);
        assert_eq!(auth_refresh_row.1, "signed_in");
        assert_eq!(auth_refresh_row.2, "connected");
        assert!(
            auth_refresh_row
                .3
                .contains("fake-claude auth-refresh evidence")
        );

        let auth_refresh_session_count: i64 = conn.query_row(
            "\
            SELECT COUNT(*)
            FROM agent_session_logs
            WHERE job_id = 'job-auth-refresh'
              AND skill_path LIKE '%auth-signin/procontract%'
            ",
            [],
            |row| row.get(0),
        )?;
        assert_eq!(auth_refresh_session_count, 1);

        let incident_row: (String, i64, i64, String) = conn.query_row(
            "\
            SELECT affected_slice_ids_json, calibration_case_count, override_count,
                   candidate_mutation_template_json
            FROM validation_incident_clusters
            WHERE incident_signature = 'cross-model-audit:job-cross-model'
            ",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )?;
        assert!(incident_row.0.contains("slice-cross-model"));
        assert_eq!(incident_row.1, 1);
        assert_eq!(incident_row.2, 0);
        assert!(incident_row.3.contains("job-cross-model"));

        let readiness_row: (
            String,
            String,
            String,
            String,
            String,
            String,
            Option<String>,
        ) = conn.query_row(
            "\
            SELECT er.slice_id,
                   er.worker_skill_id,
                   er.source_id,
                   er.enforcement_state,
                   er.last_evaluated_at,
                   vcc.worker_job_id,
                   vcc.validation_verdict_id
            FROM enforcement_readiness er
            JOIN validation_calibration_cases vcc ON vcc.slice_id = er.slice_id
            WHERE er.slice_id = 'slice-readiness'
              AND vcc.worker_job_id = 'job-readiness'
            ",
            [],
            |row| {
                Ok((
                    row.get(0)?,
                    row.get(1)?,
                    row.get(2)?,
                    row.get(3)?,
                    row.get(4)?,
                    row.get(5)?,
                    row.get(6)?,
                ))
            },
        )?;
        assert_eq!(readiness_row.0, "slice-readiness");
        assert_eq!(readiness_row.1, "procurement-ingestion/fts");
        assert_eq!(readiness_row.2, FTS_SOURCE_ID);
        assert_eq!(readiness_row.3, "dry_run");
        assert!(!readiness_row.4.trim().is_empty());
        assert_eq!(readiness_row.5, "job-readiness");
        assert!(readiness_row.6.is_none());

        let landed_cost_stage_run_id: String = conn.query_row(
            "\
            SELECT stage_run_id
            FROM landed_cost_estimates
            WHERE process_id = 'process-stage11'
              AND product_candidate_id = 'candidate-stage11'
              AND supplier_quote_id = 'quote-stage11'
            ",
            [],
            |row| row.get(0),
        )?;
        assert_eq!(landed_cost_stage_run_id, "stage-commercial-sweep");

        let net_margin_basis_hash: String = conn.query_row(
            "\
            SELECT basis_hash
            FROM candidate_net_margin_assessments
            WHERE process_id = 'process-stage11'
              AND product_candidate_id = 'candidate-stage11'
              AND stage_run_id = 'stage-commercial-sweep-net-margin'
            ",
            [],
            |row| row.get(0),
        )?;
        assert!(!net_margin_basis_hash.trim().is_empty());

        let manifest_row: (String, String, String) = conn.query_row(
            "\
            SELECT m.stage_run_id, pa.pipeline_state, pa.decision_basis_hash
            FROM manifests m
            JOIN pipeline_assessments pa ON pa.process_id = m.process_id
            WHERE m.process_id = 'process-stage11'
            ",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )?;
        assert_eq!(manifest_row.0, "stage-commercial-sweep-manifest");
        assert_eq!(manifest_row.1, "manifest_ready");
        assert!(!manifest_row.2.trim().is_empty());
        Ok(())
    }

    fn assert_health_auth_shadow_payload(output_payload: &Value) {
        assert_eq!(
            output_payload.get("autonomy_mode").and_then(Value::as_str),
            Some(super::HEALTH_AUTH_SHADOW_MODE)
        );
        let shadow_outcome = output_payload.get("shadow_outcome").unwrap_or(&Value::Null);
        assert_eq!(
            shadow_outcome.get("mode").and_then(Value::as_str),
            Some(super::HEALTH_AUTH_SHADOW_MODE)
        );
        assert_eq!(
            shadow_outcome
                .get("handler_executed")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            shadow_outcome
                .get("side_effect_persisted")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            shadow_outcome
                .get("enforcement_action")
                .and_then(Value::as_str),
            Some(super::HEALTH_AUTH_SHADOW_ENFORCEMENT_ACTION)
        );
        assert_eq!(
            shadow_outcome
                .get("production_gate_applied")
                .and_then(Value::as_bool),
            Some(false)
        );
    }

    fn assert_not_health_auth_shadow_gated(output_payload: &Value) {
        assert!(
            output_payload.get("autonomy_mode").is_none(),
            "non-health/auth cron jobs must not inherit Q6 shadow mode"
        );
        assert!(
            output_payload.get("shadow_outcome").is_none(),
            "non-health/auth cron jobs must not emit Q6 shadow outcome fields"
        );
    }

