    #[test]
    fn autonomous_worker_denial_cooldown_handles_every_reason_variant() {
        let lane = super::AutonomousWorkerLane::PtyBrowser;
        let fts_job = claimed_sync_source_job("job-fts", FTS_SOURCE_ID, FTS_SKILL_ID);
        let contracts_finder_job = claimed_sync_source_job(
            "job-contracts-finder",
            CONTRACTS_FINDER_SOURCE_ID,
            CONTRACTS_FINDER_SKILL_ID,
        );

        let mut browser_cooldowns = super::DenialCooldowns::default();
        browser_cooldowns.record(
            lane,
            &fts_job,
            &DenialReason::BrowserSlotsExhausted {
                limit: 2,
                in_use: 2,
            },
        );
        assert!(browser_cooldowns.is_active_for_claimed(lane, &fts_job));

        let mut agent_cooldowns = super::DenialCooldowns::default();
        agent_cooldowns.record(
            lane,
            &fts_job,
            &DenialReason::AgentSlotsExhausted {
                limit: 4,
                in_use: 4,
            },
        );
        assert!(agent_cooldowns.is_active_for_claimed(lane, &fts_job));

        let mut source_cooldowns = super::DenialCooldowns::default();
        source_cooldowns.record(
            lane,
            &fts_job,
            &DenialReason::SourceLaneExhausted {
                source_id: FTS_SOURCE_ID.to_owned(),
                limit: 1,
                in_use: 1,
            },
        );
        assert!(source_cooldowns.is_active_for_claimed(lane, &fts_job));
        assert!(!source_cooldowns.is_active_for_claimed(lane, &contracts_finder_job));

        let mut skill_cooldowns = super::DenialCooldowns::default();
        skill_cooldowns.record(
            lane,
            &fts_job,
            &DenialReason::SkillConcurrencyCapReached {
                key: FTS_SKILL_ID.to_owned(),
                limit: 1,
                in_use: 1,
            },
        );
        assert!(skill_cooldowns.is_active_for_claimed(lane, &fts_job));
        assert!(!skill_cooldowns.is_active_for_claimed(lane, &contracts_finder_job));
    }

    fn assert_commercial_sweep_skill_subpasses_use_arbiter_without_browser_lane(
        runtime: &super::RuntimeBootstrap,
    ) -> Result<()> {
        let (events, snapshot) = {
            let arbiter = runtime
                .resource_arbiter()
                .lock()
                .map_err(|_| anyhow::anyhow!("resource arbiter mutex poisoned"))?;
            (arbiter.events().to_vec(), arbiter.snapshot())
        };
        let commercial_skill_grants = events
            .iter()
            .filter(|event| {
                event.kind == ArbiterEventKind::Grant
                    && (event.job_id.starts_with("job-stage11-")
                        || event.job_id.starts_with("job-stage13-manifest-"))
            })
            .collect::<Vec<_>>();

        assert!(
            commercial_skill_grants
                .iter()
                .any(|event| event.job_id.starts_with("job-stage11-")),
            "commercial sweep must admit Stage 11 skill sub-passes through ResourceArbiter"
        );
        assert!(
            commercial_skill_grants
                .iter()
                .any(|event| event.job_id.starts_with("job-stage13-manifest-")),
            "commercial sweep must admit Stage 13 skill sub-passes through ResourceArbiter"
        );
        for event in &commercial_skill_grants {
            assert!(
                event.agent_slots_in_use > 0,
                "commercial sub-pass {} did not consume an agent slot",
                event.job_id
            );
            assert_eq!(
                event.browser_slots_in_use, 0,
                "commercial sub-pass {} consumed a browser slot",
                event.job_id
            );
            assert_eq!(
                event.source_lane_key, None,
                "commercial sub-pass {} consumed a source lane",
                event.job_id
            );
        }

        assert!(
            events.iter().any(|event| {
                event.kind == ArbiterEventKind::Release
                    && event.job_id.starts_with("job-stage11-")
                    && event.source_lane_key.is_none()
            }),
            "commercial Stage 11 skill sub-pass lease was not released"
        );
        assert!(
            events.iter().any(|event| {
                event.kind == ArbiterEventKind::Release
                    && event.job_id.starts_with("job-stage13-manifest-")
                    && event.source_lane_key.is_none()
            }),
            "commercial Stage 13 skill sub-pass lease was not released"
        );
        assert_eq!(snapshot.browser_slots, 0);
        assert_eq!(snapshot.agent_slots, 0);
        assert!(
            snapshot.source_lanes.is_empty(),
            "commercial sweep left source lane usage behind: {:?}",
            snapshot.source_lanes
        );
        Ok(())
    }

    #[allow(clippy::too_many_lines)]
    #[tokio::test]
    async fn autonomous_worker_routes_cron_kinds_to_side_effect_handlers() -> Result<()> {
        let (temp, mut runtime, mut cli) = bootstrap_manifest_render_runtime()?;
        cli.agent_cli_program = Some(write_fake_cron_handler_claude(temp.path())?);
        seed_stage11_minimal_graph(runtime.state_db.connection(), "GB")?;
        runtime.state_db.connection().execute(
            "\
            UPDATE product_candidates
            SET critical_attributes_json = ?1
            WHERE id = 'candidate-stage11'
            ",
            [json!({
                "installation_requirement": {
                    "requires_installation": true,
                    "requires_maintenance": false,
                    "installation_scope": "fixture_install",
                    "destination_postcode": "SW1A 1AA"
                }
            })
            .to_string()],
        )?;
        let stage11_rows = super::load_landed_cost_assessments(runtime.state_db.connection(), 10)?;
        assert_eq!(stage11_rows.len(), 1);
        assert!(
            super::installation_requirement_from_critical_attributes(&stage11_rows[0]).is_some(),
            "worker commercial fixture must exercise the Stage 11 installation labour skill"
        );
        let runner = JobRunner::new(super::LOCAL_EXECUTOR_ID);
        let cron_jobs = [
            claimed_cron_job(
                "job-source-health",
                "source_health",
                None,
                Some("source"),
                Some(FTS_SOURCE_ID),
                &json!({ "source_id": FTS_SOURCE_ID }),
            ),
            claimed_cron_job(
                "job-auth-refresh",
                "auth_refresh",
                None,
                Some("source"),
                Some(PROCONTRACT_DISCOVER_SOURCE_ID),
                &json!({
                    "source_id": PROCONTRACT_DISCOVER_SOURCE_ID,
                    "portal_id": "procontract",
                }),
            ),
            claimed_cron_job(
                "job-cross-model",
                "validation_cross_model_audit",
                None,
                Some("slice"),
                Some("slice-cross-model"),
                &json!({ "slice_id": "slice-cross-model" }),
            ),
            claimed_cron_job(
                "job-readiness",
                "validation_calibration_readiness_sweep",
                None,
                Some("slice"),
                Some("slice-readiness"),
                &json!({
                    "slice_id": "slice-readiness",
                    "source_id": FTS_SOURCE_ID,
                    "worker_skill_id": FTS_SKILL_ID,
                }),
            ),
            claimed_cron_job(
                "job-commercial-sweep",
                "commercial_sweep",
                Some("process-stage11"),
                Some("process"),
                Some("process-stage11"),
                &json!({ "stage_run_id": "stage-commercial-sweep" }),
            ),
        ];

        for claimed in cron_jobs {
            seed_running_cron_job(runtime.state_db.connection(), &claimed.id, &claimed.kind)?;
            let report =
                super::execute_claimed_workflow_job(&mut runtime, &cli, &runner, claimed.clone())
                    .await?;
            assert_eq!(report.status, "completed");
            let row: (String, String) = runtime.state_db.connection().query_row(
                "SELECT status, output_payload FROM workflow_jobs WHERE id = ?1",
                params![claimed.id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )?;
            assert_eq!(row.0, "completed");
            let output_payload: Value = serde_json::from_str(&row.1)?;
            assert_eq!(output_payload["job_kind"], claimed.kind);
            assert!(output_payload["side_effect_table"].as_str().is_some());
            match claimed.kind.as_str() {
                "source_health" | "auth_refresh" => {
                    assert_health_auth_shadow_payload(&output_payload);
                    assert!(report.summary_line.contains("autonomy_mode=shadow"));
                    assert!(
                        report
                            .summary_line
                            .contains("enforcement_action=recorded_only"),
                        "health/auth report summary must identify shadow enforcement outcome"
                    );
                }
                "validation_cross_model_audit"
                | "validation_calibration_readiness_sweep"
                | "commercial_sweep" => {
                    assert_not_health_auth_shadow_gated(&output_payload);
                    assert!(
                        !report.summary_line.contains("autonomy_mode=shadow"),
                        "validation and commercial jobs must not be gated by Q6 shadow mode"
                    );
                }
                other => assert!(
                    matches!(
                        other,
                        "source_health"
                            | "auth_refresh"
                            | "validation_cross_model_audit"
                            | "validation_calibration_readiness_sweep"
                            | "commercial_sweep"
                    ),
                    "unexpected cron handler kind `{other}`"
                ),
            }
        }

        assert_new_cron_handler_side_effects(runtime.state_db.connection())?;
        assert_commercial_sweep_skill_subpasses_use_arbiter_without_browser_lane(&runtime)?;
        Ok(())
    }

    struct FakeManifestSkillInvoker {
        payload: Option<Value>,
        fail: bool,
        invocations: usize,
    }

    impl FakeManifestSkillInvoker {
        fn success(payload: Value) -> Self {
            Self {
                payload: Some(payload),
                fail: false,
                invocations: 0,
            }
        }

        fn failure() -> Self {
            Self {
                payload: None,
                fail: true,
                invocations: 0,
            }
        }
    }

    impl super::ManifestSkillInvoker for FakeManifestSkillInvoker {
        fn invoke_manifest_skill<'a>(
            &'a mut self,
            _runtime: &'a mut super::RuntimeBootstrap,
            _skill: &'a LoadedSkill,
            _bundle: &'a super::ManifestSkillBundle,
            _cli: &'a Cli,
            _timeout_seconds: u64,
        ) -> super::ManifestSkillInvocationFuture<'a> {
            self.invocations += 1;
            let fail = self.fail;
            let payload = self.payload.clone();
            Box::pin(async move {
                if fail {
                    Err(anyhow::anyhow!("mock skill failed"))
                } else {
                    Ok(super::ManifestSkillInvocation::mock(
                        payload.unwrap_or_else(|| json!({})),
                    ))
                }
            })
        }
    }

    #[test]
    fn goods_text_fallback_qualifies_399999_physical_goods_notices() {
        // testproject1-ohhv: "399999 - Not Elsewhere Classified" notices carry no
        // parseable CPV division, so the text fallback must recover physical-goods lots.
        assert_eq!(
            super::parse_cpv_division("399999 - Not Elsewhere Classified"),
            None
        );

        // Oldham boiler-batch shape: title + payload mention concrete goods → goods.
        let payload = json!({
            "main_category": "399999 - Not Elsewhere Classified",
            "categories": "399999 - Not Elsewhere Classified",
            "detail": {"description": "Replacement gas boilers, BMS panels, pumps and valves across five sites"}
        })
        .to_string();
        assert_eq!(
            super::goods_text_classification_fallback(
                "Boiler replacement programme",
                Some(&payload)
            ),
            Some("goods"),
        );

        // Fire-alarm panel goods notice → goods (anchor wins even with generic text).
        assert_eq!(
            super::goods_text_classification_fallback(
                "Fire alarm panel supply and installation",
                None
            ),
            Some("goods"),
        );

        // Pure consultancy with no goods signal → no fallback (stays unknown).
        assert_eq!(
            super::goods_text_classification_fallback(
                "Provision of legal advisory services and consultancy",
                None
            ),
            None,
        );

        // Services-dominant text with no strong goods anchor is suppressed.
        assert_eq!(
            super::goods_text_classification_fallback(
                "Design services framework with luminaire specification consultancy",
                None
            ),
            None,
        );
    }

