    #[test]
    fn captcha_interception_without_deterministic_fallback_blocks_review() -> Result<()> {
        let mut row = stage11_row_fixture();
        row.expected_addressable_revenue_ex_vat_pence = 50_000;
        row.revenue_basis_type = "expected_value".to_owned();
        let supplier_cost = super::SupplierCostBasis {
            supplier_cost_gbp_pence: 10_000,
            basis: "test".to_owned(),
            quantity: 10.0,
            quantity_unit: Some("square meter".to_owned()),
            warnings: Vec::new(),
        };
        let mut sizing = sized_shipment_for(&row);
        sizing.warnings.push(super::Stage11Issue::warning(
            "CDP_CAPTCHA_INTERCEPTION",
            "Alibaba returned captcha.",
        ));
        let order_quantity_basis = super::infer_order_quantity_basis(&row);
        let estimate = super::build_import_landed_cost_estimate(
            &row,
            &supplier_cost,
            "stage-run-captcha-blocked",
            Some(&classified_customs_for(&row)),
            Some(&sizing),
            &freight_not_required(),
            None,
            "not_required",
            &order_quantity_basis,
            &json!({}),
            &json!({}),
        )?;

        assert_eq!(estimate.decision_grade, "blocked");
        assert!(
            estimate
                .blockers
                .contains("CDP_CAPTCHA_BLOCKED_NO_DETERMINISTIC_FALLBACK")
        );
        Ok(())
    }

    #[test]
    fn captcha_interception_with_matching_cached_fallback_can_review() -> Result<()> {
        let mut row = stage11_row_fixture();
        row.expected_addressable_revenue_ex_vat_pence = 50_000;
        row.revenue_basis_type = "expected_value".to_owned();
        let supplier_cost = super::SupplierCostBasis {
            supplier_cost_gbp_pence: 10_000,
            basis: "test".to_owned(),
            quantity: 10.0,
            quantity_unit: Some("square meter".to_owned()),
            warnings: Vec::new(),
        };
        let mut sizing = sized_shipment_for(&row);
        sizing.warnings.push(super::Stage11Issue::warning(
            "CDP_CAPTCHA_INTERCEPTION",
            "Alibaba returned captcha.",
        ));
        let source_url = row
            .source_url
            .clone()
            .ok_or_else(|| anyhow::anyhow!("fixture source URL should be set"))?;
        sizing.evidence.push(json!({
            "kind": "indexed_listing_evidence",
            "source_url": source_url,
            "deterministic_captcha_fallback": true,
        }));
        let order_quantity_basis = super::infer_order_quantity_basis(&row);
        let estimate = super::build_import_landed_cost_estimate(
            &row,
            &supplier_cost,
            "stage-run-captcha-fallback",
            Some(&classified_customs_for(&row)),
            Some(&sizing),
            &freight_not_required(),
            None,
            "not_required",
            &order_quantity_basis,
            &json!({}),
            &json!({}),
        )?;

        assert_eq!(estimate.decision_grade, "review");
        assert!(
            !estimate
                .blockers
                .contains("CDP_CAPTCHA_BLOCKED_NO_DETERMINISTIC_FALLBACK")
        );
        Ok(())
    }

    #[test]
    fn domestic_landed_cost_row_persists_with_stage_head() -> Result<()> {
        let (_temp, mut runtime) = bootstrap_validation_runtime()?;
        seed_stage11_minimal_graph(runtime.state_db.connection(), "GB")?;
        let rows = super::load_landed_cost_assessments(runtime.state_db.connection(), 10)?;
        assert_eq!(rows.len(), 1);
        let supplier_cost = super::compute_supplier_cost_basis(&rows[0]);
        let order_quantity_basis = super::infer_order_quantity_basis(&rows[0]);
        let estimate = super::build_domestic_landed_cost_estimate(
            &rows[0],
            &supplier_cost,
            None,
            "not_required",
            "stage-run-domestic-test",
            &order_quantity_basis,
            &json!({
                "hmrc_customs": "1.0.0",
                "shipment_sizing": "1.0.0",
                "searates_freight": "1.0.0",
                "simple_fx": "1.0.0",
                "uk_installation_labour": "1.0.0",
            }),
            &super::domestic_landed_cost_skill_session_ids(None),
        )?;
        super::persist_landed_cost_estimate(&mut runtime.state_db, &estimate)?;

        let (count, net_margin_base_bps, decision_grade): (i64, i64, String) =
            runtime.state_db.connection().query_row(
                "\
                SELECT COUNT(*), MAX(net_margin_base_bps), MAX(decision_grade)
                FROM landed_cost_estimates
                ",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )?;
        assert_eq!(count, 1);
        assert_eq!(net_margin_base_bps, 8000);
        assert_eq!(decision_grade, "review");

        let stage_heads: i64 = runtime.state_db.connection().query_row(
            "\
            SELECT COUNT(*)
            FROM process_stage_heads
            WHERE stage = 'landed cost'
              AND scope_kind = 'candidate_quote'
            ",
            [],
            |row| row.get(0),
        )?;
        assert_eq!(stage_heads, 1);
        Ok(())
    }

    #[test]
    fn maintenance_period_estimate_persists_after_landed_cost_row() -> Result<()> {
        let (_temp, mut runtime) = bootstrap_validation_runtime()?;
        seed_stage11_minimal_graph(runtime.state_db.connection(), "GB")?;
        runtime.state_db.connection().execute(
            "\
            UPDATE product_candidates
            SET critical_attributes_json = ?1
            WHERE id = 'candidate-stage11'
            ",
            [json!({
                "installation_requirement": {
                    "requires_installation": true,
                    "requires_maintenance": true,
                    "installation_scope": "playground_install",
                    "maintenance_schedule": {
                        "visits_per_year": 4,
                        "term_years": 3,
                        "visit_scope": "quarterly inspection and minor service"
                    }
                }
            })
            .to_string()],
        )?;
        let rows = super::load_landed_cost_assessments(runtime.state_db.connection(), 10)?;
        assert_eq!(rows.len(), 1);
        let supplier_cost = super::compute_supplier_cost_basis(&rows[0]);
        let order_quantity_basis = super::infer_order_quantity_basis(&rows[0]);
        let estimate = super::build_domestic_landed_cost_estimate(
            &rows[0],
            &supplier_cost,
            None,
            "not_required",
            "stage-run-maintenance-persist-test",
            &order_quantity_basis,
            &json!({
                "hmrc_customs": "1.0.0",
                "shipment_sizing": "1.0.0",
                "searates_freight": "1.0.0",
                "simple_fx": "1.0.0",
                "uk_installation_labour": "1.0.0",
            }),
            &super::domestic_landed_cost_skill_session_ids(None),
        )?;
        super::persist_landed_cost_estimate(&mut runtime.state_db, &estimate)?;
        let maintenance = super::maintenance_period_estimate_for_row(&rows[0], &estimate)
            .ok_or_else(|| anyhow::anyhow!("expected maintenance estimate"))?;
        super::persist_maintenance_period_estimate(&mut runtime.state_db, &maintenance)?;

        let persisted: (i64, String, i64, i64, i64) = runtime.state_db.connection().query_row(
            "\
                SELECT COUNT(*), MAX(visit_scope), MAX(visits_per_year), MAX(term_years),
                       MAX(total_visible_term_opex_gbp_pence)
                FROM maintenance_period_estimates
                WHERE product_candidate_id = 'candidate-stage11'
                  AND landed_cost_estimate_id = ?1
                ",
            [estimate.id],
            |row| {
                Ok((
                    row.get(0)?,
                    row.get(1)?,
                    row.get(2)?,
                    row.get(3)?,
                    row.get(4)?,
                ))
            },
        )?;
        assert_eq!(
            persisted,
            (
                1,
                "quarterly inspection and minor service".to_owned(),
                4,
                3,
                720_000
            )
        );
        Ok(())
    }

    #[test]
    fn l5_decision_grade_feature_flag_defaults_to_decision_grade() {
        assert!(matches!(
            super::LandedCostPathMode::from_env_value(None),
            super::LandedCostPathMode::DecisionGrade
        ));
        assert!(matches!(
            super::LandedCostPathMode::from_env_value(Some("")),
            super::LandedCostPathMode::DecisionGrade
        ));
        assert!(matches!(
            super::LandedCostPathMode::from_env_value(Some("screening_grade")),
            super::LandedCostPathMode::ScreeningGradeOnly
        ));
        assert!(matches!(
            super::LandedCostPathMode::from_env_value(Some("off")),
            super::LandedCostPathMode::ScreeningGradeOnly
        ));
        assert!(matches!(
            super::LandedCostPathMode::from_env_value(Some("shadow")),
            super::LandedCostPathMode::ShadowCompare
        ));
        assert!(matches!(
            super::LandedCostPathMode::from_env_value(Some("decision-grade")),
            super::LandedCostPathMode::DecisionGrade
        ));
        assert!(matches!(
            super::LandedCostPathMode::from_env_value(Some("unexpected")),
            super::LandedCostPathMode::DecisionGrade
        ));
    }

