    #[test]
    #[allow(clippy::cast_possible_truncation, clippy::too_many_lines)]
    fn hmrc_rebar_api_measure_canary_detects_safeguard_branch() {
        let payload = json!({
            "data": {
                "attributes": {
                    "goods_nomenclature_item_id": "7214200020",
                    "producline_suffix": "80"
                }
            },
            "included": [
                {
                    "type": "measure_type",
                    "id": "103",
                    "attributes": {"description": "Third country duty"}
                },
                {
                    "type": "measure_type",
                    "id": "305",
                    "attributes": {"description": "Value added tax"}
                },
                {
                    "type": "measure_type",
                    "id": "696",
                    "attributes": {"description": "Additional duties (safeguard)"}
                },
                {
                    "type": "measure_component",
                    "id": "component-basic",
                    "attributes": {"duty_amount": 0.0}
                },
                {
                    "type": "measure_component",
                    "id": "component-vat",
                    "attributes": {"duty_amount": 20.0}
                },
                {
                    "type": "measure_component",
                    "id": "component-safeguard",
                    "attributes": {"duty_amount": 25.0}
                },
                {
                    "type": "measure",
                    "id": "measure-basic",
                    "attributes": {"import": true},
                    "relationships": {
                        "measure_type": {"data": {"id": "103", "type": "measure_type"}},
                        "measure_components": {
                            "data": [{"id": "component-basic", "type": "measure_component"}]
                        }
                    }
                },
                {
                    "type": "measure",
                    "id": "measure-vat",
                    "attributes": {"import": true},
                    "relationships": {
                        "measure_type": {"data": {"id": "305", "type": "measure_type"}},
                        "measure_components": {
                            "data": [{"id": "component-vat", "type": "measure_component"}]
                        }
                    }
                },
                {
                    "type": "measure",
                    "id": "measure-safeguard",
                    "attributes": {"import": true},
                    "relationships": {
                        "measure_type": {"data": {"id": "696", "type": "measure_type"}},
                        "measure_components": {
                            "data": [{"id": "component-safeguard", "type": "measure_component"}]
                        }
                    }
                }
            ]
        });
        let included = payload
            .get("included")
            .and_then(Value::as_array)
            .expect("included array");
        let description_for_type = |type_id: &str| {
            included
                .iter()
                .find(|entry| {
                    entry.get("type").and_then(Value::as_str) == Some("measure_type")
                        && entry.get("id").and_then(Value::as_str) == Some(type_id)
                })
                .and_then(|entry| entry.pointer("/attributes/description"))
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_ascii_lowercase()
        };
        let amount_for_component = |component_id: &str| {
            included
                .iter()
                .find(|entry| {
                    entry.get("type").and_then(Value::as_str) == Some("measure_component")
                        && entry.get("id").and_then(Value::as_str) == Some(component_id)
                })
                .and_then(|entry| entry.pointer("/attributes/duty_amount"))
                .and_then(Value::as_f64)
                .unwrap_or(0.0)
        };

        let mut basic_bps = None;
        let mut vat_bps = None;
        let mut safeguard_bps = None;
        for measure in included
            .iter()
            .filter(|entry| entry.get("type").and_then(Value::as_str) == Some("measure"))
        {
            let type_id = measure
                .pointer("/relationships/measure_type/data/id")
                .and_then(Value::as_str)
                .unwrap_or("");
            let description = description_for_type(type_id);
            let component_id = measure
                .pointer("/relationships/measure_components/data/0/id")
                .and_then(Value::as_str)
                .unwrap_or("");
            let amount_bps = (amount_for_component(component_id) * 100.0).round() as i64;
            if description.contains("third country duty") {
                basic_bps = Some(amount_bps);
            } else if description.contains("value added tax") {
                vat_bps = Some(amount_bps);
            } else if description.contains("safeguard") {
                safeguard_bps = Some(amount_bps);
            }
        }

        assert_eq!(
            payload.pointer("/data/attributes/goods_nomenclature_item_id"),
            Some(&Value::String("7214200020".to_owned()))
        );
        assert_eq!(
            payload.pointer("/data/attributes/producline_suffix"),
            Some(&Value::String("80".to_owned()))
        );
        assert_eq!(basic_bps, Some(0));
        assert_eq!(vat_bps, Some(2000));
        assert_eq!(safeguard_bps, Some(2500));
    }

    /// Regression: `run_bound_skill` used to mark procurement ingestion jobs
    /// as `completed` even when the nested agent failed upstream and never
    /// produced a result contract. The guard now in place asks
    /// `procurement_skill_requires_result_contract` whether a missing
    /// result file should promote to a hard failure. Non-procurement skills
    /// (pdf-extraction/*, manifest-generation, etc.) can legitimately finish
    /// without a result file, so they must continue returning `false`.
    #[test]
    fn procurement_skills_require_result_contract_to_complete() {
        assert!(super::procurement_skill_requires_result_contract(
            "procurement-ingestion/procontract-discover"
        ));
        assert!(super::procurement_skill_requires_result_contract(
            "procurement-ingestion/procontract-register-interest"
        ));
        assert!(super::procurement_skill_requires_result_contract(
            "procurement-ingestion/procontract-enrich-tender"
        ));
        assert!(!super::procurement_skill_requires_result_contract(
            "pdf-extraction/extract-document-semantics"
        ));
        assert!(!super::procurement_skill_requires_result_contract(
            "manifest-generation"
        ));
        assert!(!super::procurement_skill_requires_result_contract(""));
    }

    /// Regression: verifies that when a procurement ingestion skill produces
    /// no result contract, the failure helper used by `run_bound_skill`
    /// transitions the workflow job from `running` to `failed` with
    /// `AGENT_RUN_FAILED` context. Before the fix, the job was
    /// unconditionally marked `completed`, hiding upstream agent crashes.
    #[test]
    fn missing_procurement_result_contract_marks_job_failed() -> Result<()> {
        let (_temp, mut runtime) = bootstrap_validation_runtime()?;
        let job_id = "job-regression-missing-result";
        runtime.state_db.connection().execute(
            "\
            INSERT INTO workflow_jobs (
              id, kind, scope_kind, scope_id, status, input_payload, validation_required,
              parent_job_id, validation_verdict_id
            ) VALUES (?1, 'sync_source', 'source', 'procontract', 'running',
                      ?2, 0, NULL, NULL)
            ",
            params![job_id, json!({"source_id": "procontract"}).to_string()],
        )?;

        let report = super::fail_with_manifest(
            &mut runtime,
            job_id,
            super::ErrorCode::AgentRunFailed,
            "procurement skill `procurement-ingestion/procontract-discover` exited without writing a result contract",
            None,
            None,
            None,
            "ingest",
            "agent_execute",
            json!({"skill_id": "procurement-ingestion/procontract-discover"}),
        )?;
        assert_eq!(report.status, "failed");

        let (status, last_error): (String, Option<String>) =
            runtime.state_db.connection().query_row(
                "SELECT status, last_error FROM workflow_jobs WHERE id = ?1",
                params![job_id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )?;
        assert_eq!(status, "failed");
        let last_error = last_error.unwrap_or_default();
        assert!(
            last_error.contains("without writing a result contract"),
            "expected silent-success regression message, got: {last_error}"
        );

        let manifest_rows: i64 = runtime.state_db.connection().query_row(
            "SELECT COUNT(*) FROM error_manifests WHERE job_id = ?1",
            params![job_id],
            |row| row.get(0),
        )?;
        assert!(
            manifest_rows >= 1,
            "expected at least one error manifest row for failed procurement job"
        );
        Ok(())
    }

